 public nullintfloatstringfalsemysqli_result::fetch_column
 intcolumn0

&style.procedural;

 nullintfloatstringfalsemysqli_fetch_column
 mysqli_resultresult
 intcolumn0


 Fetches one row of data from the result set and returns the 0-indexed column.
 Each subsequent call to this function will return the value from the next row
 within the result set, or &false; if there are no more rows.

&database.fetch-null;

&reftitle.parameters;



  &mysqli.result.description;

   column


     0-indexed number of the column you wish to retrieve from the row. If
     no value is supplied, the first column will be returned.

&reftitle.returnvalues;
Returns a single column from the next row of a result set or &false; if there are no more rows.
There is no way to return another column from the same row if you use this function to retrieve data.

  &reftitle.examples;

   mysqli_result::fetch_column example
   &style.oop;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$mysqli = new mysqli("localhost", "my_user", "my_password", "world");

$query = "SELECT CountryCode, Name FROM City ORDER BY ID DESC LIMIT 5";

$result = $mysqli->query($query);

/* fetch a single value from the second column */
while ($Name = $result->fetch_column(1)) {
    printf("%s\n", $Name);
}


   &style.procedural;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$mysqli = mysqli_connect("localhost", "my_user", "my_password", "world");

$query = "SELECT CountryCode, Name FROM City ORDER BY ID DESC LIMIT 5";

$result = mysqli_query($mysqli, $query);

/* fetch a single value from the second column */
while ($Name = mysqli_fetch_column($result, 1)) {
    printf("%s\n", $Name);
}


